import{_ as a,o as i,a as t,b as n}from"./app.C41L12d5.js";const r="/ascendc.github.io/assets/enque-42.Kbl9mg7y.png",l=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"资源管理","link":"/api/SIMD-API/basic_api/resource_management/resource_management"},{"text":"TBuf","link":"/api/SIMD-API/basic_api/resource_management/TBuf/TBuf"},{"text":"TBuf简介","link":"/api/SIMD-API/basic_api/resource_management/TBuf/TBuf_intro"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/resource_management/TBuf/TBuf_intro.md","filePath":"api/SIMD-API/basic_api/resource_management/TBuf/TBuf_intro.md","lastUpdated":1785832713000}'),s={name:"api/SIMD-API/basic_api/resource_management/TBuf/TBuf_intro.md"};function u(f,e,p,_,o,T){return i(),t("div",null,[...e[0]||(e[0]=[n('<div><article class="markdown-body"><h1>TBuf简介<span id="ZH-CN_TOPIC_0000001645413417"></span></h1><p>使用Ascend C编程的过程中，可能会用到一些临时变量。这些临时变量占用的内存可以使用TBuf数据结构来管理，存储位置通过模板参数来设置，可以设置为不同的<a href="../../aux_data_structures//TPosition.html">TPosition</a>逻辑位置。</p><p>TBuf继承自TQueBind父类，继承关系如下：</p><p><img src="'+r+'" alt></p><p>TBuf占用的存储空间通过TPipe进行管理，您可以通过<a href="../TPipe/InitBuffer.html">InitBuffer</a>接口为TBuf进行内存初始化操作，之后即可通过<a href="Get.html">Get</a>获取指定长度的Tensor参与计算。</p><p>使用<a href="../TPipe/InitBuffer.html">InitBuffer</a>为TBuf分配内存和为队列分配内存有以下差异：</p><ul><li>为TBuf分配的内存空间只能参与计算，无法执行队列的入队出队操作。</li><li>调用一次内存初始化接口，TPipe只会为TBuf分配一块内存，为队列可以通过参数设置申请多块内存。如果要使用多个临时变量，需要定义多个TBuf数据结构，对每个TBuf数据结构分别调用<a href="../TPipe/InitBuffer.html">InitBuffer</a>接口进行内存初始化。</li><li>TBuf获取的Tensor无需释放。</li></ul></article></div>',1)])])}const m=a(s,[["render",u]]);export{l as __pageData,m as default};
